const respuesta_raw = $input.first().json.choices[0].message.content;
const respuesta_limpia = respuesta_raw
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(respuesta_limpia);
} catch(e) {
  parsed = {
    respuesta_usuario: respuesta_raw,
    accion: "responder",
    estado: "calificando",
    datos_capturados: {
      nombre: null,
      tratamiento_interes: null,
      urgencia: null,
      presupuesto: null,
      disponibilidad: null,
      email: null,
      confirmado: null
    }
  };
}

const numero = $('Webhook').first().json.body.numero;
const wa_phone_id = $('Webhook').first().json.body.wa_phone_id;
const mensaje_actual = $('Webhook').first().json.body.mensaje;
const timestamp = new Date().toISOString();
const tokens_usados = $input.first().json.usage?.total_tokens || 0;

return [{
  json: {
    numero,
    wa_phone_id,
    mensaje_actual,
    timestamp,
    tokens_usados,
    respuesta_usuario: parsed.respuesta_usuario,
    accion: parsed.accion,
    estado: parsed.estado || 'calificando',
    motivo_escalacion: parsed.motivo_escalacion || 'Lead solicito hablar con un humano',
    datos_capturados: parsed.datos_capturados
  }
}];

const parsear = $('Parsear respuesta').first().json;

